static inline void hmx_cvt_hf_acc_select_bias_intrinsic(int bias_idx, int retain_acc) {
#if HTP_LPBQ_HAS_TARGET_HMX_INTRINSICS
  uint32_t rs = ((uint32_t) (bias_idx & 3) << 12) | (retain_acc ? 1u : 0u);
  Q6_cvt_hf_acc_R((int32_t) rs);
#else
  hmx_cvt_hf_acc_select_bias(bias_idx, retain_acc);
#endif
}

static inline void hmx_cvt_hf_acc_raw_selector_intrinsic(int selector) {
#if HTP_LPBQ_HAS_TARGET_HMX_INTRINSICS
  Q6_cvt_hf_acc_R((int32_t) selector);
#else
  hmx_cvt_hf_only_selector(selector);
#endif
}

static inline void hmx_cvt_uh_acc_select_intrinsic(int selector, int shape_2x2) {
#if HTP_LPBQ_HAS_TARGET_HMX_INTRINSICS
  if (shape_2x2) {
    Q6_cvt_uh_acc_R_2x2((int32_t) selector);
  } else {
    Q6_cvt_uh_acc_R_2x1((int32_t) selector);
  }
#else
  if (shape_2x2) {
    asm volatile("cvt.uh = acc(%0):2x2" ::"r"(selector) : "memory");
  } else {
    hmx_cvt_uh_2x1_only_selector(selector);
  }
#endif
}

static inline void hmx_store_cvt_to_vtcm_intrinsic(void *out_2kb_vtcm, uint32_t spatial_rs) {
#if HTP_LPBQ_HAS_TARGET_HMX_INTRINSICS
  Q6_mxmem_cvt_AR(out_2kb_vtcm, (int32_t) spatial_rs);
#else
  hmx_store_cvt_to_vtcm(out_2kb_vtcm, spatial_rs);
#endif
}

static inline void hmx_acc_mxshl_acc_intrinsic() {
#if HTP_LPBQ_HAS_TARGET_HMX_INTRINSICS
  Q6_acc_mxshl_acc();
#endif
}

static inline void hmx_consume_accumulator_hf_selector_intrinsic(__fp16 *out, int selector) {
  const int bias_idx = (selector >> 12) & 3;
  hmx_cvt_hf_acc_select_bias_intrinsic(bias_idx, selector & 1);
  hmx_store_cvt_to_vtcm_intrinsic(out, 0);
}

static inline void hmx_store_direct_hf_intrinsic(__fp16 *out_hf, int variant) {
#if HTP_LPBQ_HAS_TARGET_HMX_INTRINSICS
  switch (variant) {
    case 0:
      Q6_mxmem_AR_before_hf(out_hf, 0);
      break;
    case 1:
      Q6_mxmem_AR_after_hf(out_hf, 0);
      break;
    case 2:
      Q6_mxmem_AR_before_retain_hf(out_hf, 0);
      break;
    case 3:
      Q6_mxmem_AR_after_retain_hf(out_hf, 0);
      break;
    case 4:
      Q6_mxmem_AR_before_pos_hf(out_hf, 0);
      break;
    case 5:
      Q6_mxmem_AR_after_pos_hf(out_hf, 0);
      break;
    case 6:
      Q6_mxmem_AR_before_retain_pos_hf(out_hf, 0);
      break;
    case 7:
    default:
      Q6_mxmem_AR_after_retain_pos_hf(out_hf, 0);
      break;
  }
#else
  switch (variant & 3) {
    case 0:
      asm volatile("mxmem(%0, %1):before.hf = acc" ::"r"(out_hf), "r"(0) : "memory");
      break;
    case 1:
      asm volatile("mxmem(%0, %1):after.hf = acc" ::"r"(out_hf), "r"(0) : "memory");
      break;
    case 2:
      asm volatile("mxmem(%0, %1):before:retain.hf = acc" ::"r"(out_hf), "r"(0) : "memory");
      break;
    case 3:
    default:
      asm volatile("mxmem(%0, %1):after:retain.hf = acc" ::"r"(out_hf), "r"(0) : "memory");
      break;
  }
#endif
}

