static int hmx_int8_lpbq_u8_safe_k4_probe_run(struct HmxInt8GateResult *results, int max_results) {
  constexpr int n_patterns = 4;
  if (!results || max_results < n_patterns) {
    return -1;
  }

  uint8_t *vtcm = (uint8_t *) vtcm_manager_get_vtcm_base();
  uint8_t  *a       = vtcm;
  int8_t   *b       = (int8_t *) (vtcm + 0x1000);
  uint16_t *out     = (uint16_t *) (vtcm + 0x2000);
  __fp16   *scales  = (__fp16 *) (vtcm + 0x3000);
  uint8_t  *q_u     = vtcm + 0x4000;
  int8_t   *w_ref   = (int8_t *) (vtcm + 0x5000);
  int32_t  *cpu_ref = (int32_t *) (vtcm + 0x6000);
  int32_t  *acc     = (int32_t *) (vtcm + 0x7000);

  hmx_manager_enable_execution();
  hmx_unit_acquire();
  hmx_int8_lpbq_init_power2_scales(scales, 1.0f);

  for (int pattern = 0; pattern < n_patterns; ++pattern) {
    memset(cpu_ref, 0, 32u * 32u * sizeof(int32_t));
    memset(acc, 0, 32u * 32u * sizeof(int32_t));

    for (int r = 0; r < 32; ++r) {
      for (int k = 0; k < 32; ++k) {
        q_u[r * 32 + k] = (uint8_t) ((r * 29 + k * 17 + 131 + pattern * 23) & 255);
      }
    }

    int max_group_abs_sum = 0;
    for (int kg = 0; kg < 8; ++kg) {
      for (int c = 0; c < 32; ++c) {
        int vals[4] = {0, 0, 0, 0};
        if (pattern == 0) {
          vals[0] = ((c * 7 + kg * 11 + 3) % 41) - 20;
          vals[1] = ((c * 5 + kg * 13 + 9) % 41) - 20;
          vals[2] = ((c * 3 + kg * 17 + 5) % 41) - 20;
          vals[3] = ((c * 19 + kg * 2 + 1) % 41) - 20;
        } else if (pattern == 1) {
          vals[0] = 32; vals[1] = 32; vals[2] = 32; vals[3] = 32;
        } else if (pattern == 2) {
          vals[0] = -32; vals[1] = -32; vals[2] = -32; vals[3] = -32;
        } else {
          vals[0] = 64; vals[1] = -32; vals[2] = 16; vals[3] = -16;
        }
        int group_abs_sum = 0;
        for (int lane = 0; lane < 4; ++lane) {
          const int k = kg * 4 + lane;
          const int v = vals[lane];
          w_ref[k * 32 + c] = (int8_t) v;
          group_abs_sum += v < 0 ? -v : v;
        }
        if (group_abs_sum > max_group_abs_sum) {
          max_group_abs_sum = group_abs_sum;
        }
      }
    }

    for (int r = 0; r < 32; ++r) {
      for (int c = 0; c < 32; ++c) {
        int32_t sum = 0;
        for (int k = 0; k < 32; ++k) {
          sum += (int32_t) q_u[r * 32 + k] * (int32_t) w_ref[k * 32 + c];
        }
        cpu_ref[r * 32 + c] = sum;
      }
    }

    for (int k_in = 0; k_in < 32; k_in += 4) {
      hmx_int8_pack_activation_u8_k4_local(a, q_u, k_in);
      hmx_int8_pack_weight_b_full_k4_local(b, w_ref, k_in);
      hmx_int8_raw_dot_tile_b_variant_output(a, b, (uint8_t *) out, scales, 9, 16);
      for (int r = 0; r < 32; ++r) {
        for (int c = 0; c < 32; ++c) {
          const int idx = r * 32 + c;
          const int hmx_idx = hmx_tile_idx_32(r, c);
          acc[idx] += hmx_gate_decode_uh_signed(out[hmx_idx]);
        }
      }
    }

    int    first_bad = -1;
    int    max_err_i = 0;
    double sq_err = 0.0;
    for (int i = 0; i < 32 * 32; ++i) {
      int err = acc[i] - cpu_ref[i];
      if (err < 0) {
        err = -err;
      }
      if (err > max_err_i) {
        max_err_i = err;
        first_bad = i;
      }
      sq_err += (double) err * (double) err;
    }

    const int sample = first_bad >= 0 ? first_bad : 0;
    HmxInt8GateResult *res = &results[pattern];
    memset(res, 0, sizeof(*res));
    res->reserved    = 5500 + pattern;
    res->variant     = 9;
    res->output_kind = max_err_i == 0 && max_group_abs_sum <= 128 ? 0 : -55;
    res->tile_bytes  = 4;
    res->selector    = first_bad;
    res->expected    = (float) cpu_ref[0];
    res->first8[0]   = (float) acc[0];
    res->first8[1]   = (float) cpu_ref[0];
    res->first8[2]   = (float) max_err_i;
    res->first8[3]   = (float) sqrt(sq_err / (32.0 * 32.0));
    res->first8[4]   = (float) sample;
    res->first8[5]   = (float) acc[sample];
    res->first8[6]   = (float) cpu_ref[sample];
    res->first8[7]   = 1.0f;
    res->min_value   = (float) max_group_abs_sum;
    res->max_value   = (float) max_err_i;
    res->mean_value  = (float) first_bad;
    res->rmse        = res->first8[3];
  }

  hmx_unit_release();
  hmx_manager_disable_execution();
  // Standalone probe mode: always return rows so the host log shows which safe
  // K4 patterns failed.  Pass/fail is carried by output_kind.
  return 0;
}

static void hmx_int8_pack_activation_u8_k4_scalar_probe(uint8_t *dst, int kk, int lane_mode, uint8_t value) {
  memset(dst, 0, HMX_FP16_TILE_SIZE);
  const int base = 4 * kk + 1;
  if (lane_mode == 0 || lane_mode == 2) {
    dst[base - 1] = value;
  }
  if (lane_mode == 1 || lane_mode == 2) {
    dst[base] = value;
  }
}

static void hmx_int8_pack_weight_b_k4_scalar_probe(int8_t *dst, int kk, int weight_mode, int8_t value) {
  memset(dst, 0, HMX_FP16_TILE_SIZE);
  if (weight_mode == 0) {
    dst[kk] = value;
    return;
  }
  const int base = 128 * (kk / 2) + 2 * (kk & 1);
  if (base + 1 < HMX_FP16_TILE_SIZE) {
    dst[base + 0] = value;
    dst[base + 1] = value;
  }
}

static int hmx_int8_lpbq_u8_k4_scalar_debug_probe_run(struct HmxInt8GateResult *results, int max_results) {
  const uint8_t q_values[] = {1, 2, 128, 255};
  const int8_t  w_values[] = {1, -1, 32, -32};
  constexpr int n_q = (int) (sizeof(q_values) / sizeof(q_values[0]));
  constexpr int n_w = (int) (sizeof(w_values) / sizeof(w_values[0]));
  constexpr int n_results = 4 * 2 * 3 * 2 * 2 * n_q * n_w;
  if (!results || max_results < n_results) {
    return -1;
  }

  uint8_t *vtcm = (uint8_t *) vtcm_manager_get_vtcm_base();
  uint8_t  *a      = vtcm;
  int8_t   *b      = (int8_t *) (vtcm + 0x1000);
  uint16_t *out    = (uint16_t *) (vtcm + 0x2000);
  __fp16   *scales = (__fp16 *) (vtcm + 0x3000);

  hmx_manager_enable_execution();
  hmx_unit_acquire();

  int result_idx = 0;
  for (int kk = 0; kk < 4; ++kk) {
    for (int variant_i = 0; variant_i < 2; ++variant_i) {
      const int variant = variant_i == 0 ? 8 : 9;
      for (int lane_mode = 0; lane_mode < 3; ++lane_mode) {
        for (int weight_mode = 0; weight_mode < 2; ++weight_mode) {
          for (int scale_mode = 0; scale_mode < 2; ++scale_mode) {
            if (scale_mode == 0) {
              hmx_gate_init_scales(scales, 0);
            } else {
              hmx_int8_lpbq_init_power2_scales(scales, 1.0f);
            }
            for (int qi = 0; qi < n_q; ++qi) {
              for (int wi = 0; wi < n_w; ++wi) {
                const uint8_t q = q_values[qi];
                const int8_t  w = w_values[wi];
                hmx_int8_pack_activation_u8_k4_scalar_probe(a, kk, lane_mode, q);
                hmx_int8_pack_weight_b_k4_scalar_probe(b, kk, weight_mode, w);
                hmx_int8_raw_dot_tile_b_variant_output(a, b, (uint8_t *) out, scales, variant, 16);

                const int got = hmx_gate_decode_uh_signed(out[hmx_tile_idx_32(0, 0)]);
                const int ref = (int) q * (int) w;
                int err = got - ref;
                if (err < 0) {
                  err = -err;
                }

                HmxInt8GateResult *res = &results[result_idx++];
                memset(res, 0, sizeof(*res));
                res->reserved    = 5600 + result_idx;
                res->variant     = variant;
                res->output_kind = err == 0 ? 0 : -56;
                res->tile_bytes  = kk * 1000 + lane_mode * 100 + weight_mode * 10 + scale_mode;
                res->selector    = (int) q;
                res->expected    = (float) ref;
                res->first8[0]   = (float) got;
                res->first8[1]   = (float) ref;
                res->first8[2]   = (float) q;
                res->first8[3]   = (float) w;
                res->first8[4]   = (float) kk;
                res->first8[5]   = (float) lane_mode;
                res->first8[6]   = (float) weight_mode;
                res->first8[7]   = (float) scale_mode;
                res->min_value   = (float) err;
                res->max_value   = (float) err;
                res->mean_value  = (float) got;
                res->rmse        = (float) err;
              }
            }
          }
        }
      }
    }
  }

  hmx_unit_release();
  hmx_manager_disable_execution();
  return 0;
}

static void hmx_int8_lpbq_pack_activation_u8_k4_split_lanes(uint8_t *dst, const uint8_t *q_u, int k_in) {
  memset(dst, 0, HMX_FP16_TILE_SIZE);
  for (int r = 0; r < 32; ++r) {
    for (int kk = 0; kk < 4; ++kk) {
      const int     k = k_in + kk;
      const uint8_t q = q_u[r * 32 + k];
      const uint8_t q0 = (uint8_t) ((q >> 1) << 1);
      const uint8_t q1 = q == 255 ? 255 : (uint8_t) ((q - (q >> 1)) << 1);
      const int     base = 128 * (r / 2) + 4 * kk + 2 * (r & 1);
      if (base + 1 < HMX_FP16_TILE_SIZE) {
        dst[base + 0] = q0;
        dst[base + 1] = q1;
      }
    }
  }
}

static void hmx_int8_lpbq_pack_activation_u8_k4_twin_lanes_shifted(uint8_t *dst, const uint8_t *q_u, int k_in) {
  memset(dst, 0, HMX_FP16_TILE_SIZE);
  for (int r = 0; r < 32; ++r) {
    for (int kk = 0; kk < 4; ++kk) {
      const int     k = k_in + kk;
      const uint8_t q = q_u[r * 32 + k];
      const int     base = 128 * (r / 2) + 4 * kk + 2 * (r & 1) + 1;
      if (base + 1 < HMX_FP16_TILE_SIZE) {
        // LPBQ deploy-v1 full-U8 note: mode61 showed output(0,0) consumes
        // activation offsets 4*k+1 and 4*k+2.  This is still one
        // activation.ub * weight.b issue; it is not a positive/negative or
        // lo/hi replay path.
        dst[base + 0] = q;
        dst[base + 1] = q;
      }
    }
  }
}

static void hmx_int8_lpbq_pack_activation_u8_k4_singlepass_pair(uint8_t *dst, const uint8_t *q_u, int k_in) {
  memset(dst, 0, HMX_FP16_TILE_SIZE);
  for (int r = 0; r < 32; ++r) {
    for (int kk = 0; kk < 4; ++kk) {
      const int     k = k_in + kk;
      const uint8_t q = q_u[r * 32 + k];
      const int     pair_base = 128 * (r / 2);
      int           off0 = 0;
      int           off1 = 0;
      if ((r & 1) == 0) {
        off0 = pair_base + 4 * kk + 1;
        off1 = pair_base + 4 * kk + 2;
      } else {
        off0 = pair_base + 4 * kk + 3;
        off1 = (pair_base + 128 + 4 * kk) & (HMX_FP16_TILE_SIZE - 1);
      }
      // Same single HMX issue as the even-row probe, but odd rows place their
      // high half-lane at the start of the next row-pair block.
      if (off0 >= 0 && off0 < HMX_FP16_TILE_SIZE) {
        dst[off0] = q;
      }
      if (off1 >= 0 && off1 < HMX_FP16_TILE_SIZE) {
        dst[off1] = q;
      }
    }
  }
}

static void hmx_int8_lpbq_pack_activation_u8_k4_singlepass_pair_stride(uint8_t *dst, const uint8_t *q_u,
                                                                        int k_stride, int k_in) {
  memset(dst, 0, HMX_FP16_TILE_SIZE);
  for (int r = 0; r < 32; ++r) {
    for (int kk = 0; kk < 4; ++kk) {
      const int     k = k_in + kk;
      const uint8_t q = q_u[(size_t) r * (size_t) k_stride + (size_t) k];
      const int     pair_base = 128 * (r / 2);
      int           off0 = 0;
      int           off1 = 0;
      if ((r & 1) == 0) {
        off0 = pair_base + 4 * kk + 1;
        off1 = pair_base + 4 * kk + 2;
      } else {
        off0 = pair_base + 4 * kk + 3;
        off1 = (pair_base + 128 + 4 * kk) & (HMX_FP16_TILE_SIZE - 1);
      }
      if (off0 >= 0 && off0 < HMX_FP16_TILE_SIZE) {
        dst[off0] = q;
      }
      if (off1 >= 0 && off1 < HMX_FP16_TILE_SIZE) {
        dst[off1] = q;
      }
    }
  }
}

static void hmx_int8_lpbq_pack_activation_u8_k4_mode(uint8_t *dst, const uint8_t *q_u, int k_in, int pack_mode) {
  if (pack_mode == 0) {
    hmx_int8_pack_activation_u8_k4_local(dst, q_u, k_in);
  } else if (pack_mode == 1) {
    hmx_int8_pack_activation_u8_k4_local_both_lanes(dst, q_u, k_in);
  } else if (pack_mode == 2) {
    // LPBQ deploy-v1 full-u8 probe: keep this as a diagnostic candidate for
    // single-pass q_u*w. It does not split positive/negative products; it only
    // tries the two activation byte lanes available inside activation.ub.
    hmx_int8_lpbq_pack_activation_u8_k4_split_lanes(dst, q_u, k_in);
  } else {
    hmx_int8_lpbq_pack_activation_u8_k4_twin_lanes_shifted(dst, q_u, k_in);
  }
}

static void hmx_int8_lpbq_fill_full_u8_offset_case(uint8_t *q_u, int8_t *w_ref, int32_t *raw_ref,
                                                   int32_t *signed_ref, int32_t *sum_w, int pattern) {
  for (int c = 0; c < 32; ++c) {
    sum_w[c] = 0;
  }

  for (int r = 0; r < 32; ++r) {
    for (int k = 0; k < 32; ++k) {
      int q = 0;
      if (pattern == 0) {
        q = 128 + ((r + k) & 7);
      } else if (pattern == 1) {
        q = 8 + ((r * 13 + k * 29 + 17) % 240);
      } else {
        q = (r == 0 && k == 0) ? 255 : ((r * 19 + k * 11 + 3) & 255);
      }
      q_u[r * 32 + k] = (uint8_t) q;
    }
  }

  for (int k = 0; k < 32; ++k) {
    for (int c = 0; c < 32; ++c) {
      int w = 0;
      if (pattern == 0) {
        w = (k & 1) ? -1 : 1;
      } else if (pattern == 1) {
        w = ((c * 3 + k * 5 + 1) % 7) - 3;
      } else {
        w = ((c * 5 + k * 7 + 2) % 5) - 2;
      }
      w_ref[k * 32 + c] = (int8_t) w;
      sum_w[c] += w;
    }
  }

  for (int r = 0; r < 32; ++r) {
    for (int c = 0; c < 32; ++c) {
      int32_t raw = 0;
      int32_t signed_sum = 0;
      for (int k = 0; k < 32; ++k) {
        const int q = (int) q_u[r * 32 + k];
        const int w = (int) w_ref[k * 32 + c];
        raw += q * w;
        signed_sum += (q - 128) * w;
      }
      raw_ref[r * 32 + c]    = raw;
      signed_ref[r * 32 + c] = signed_sum;
    }
  }
}

static void hmx_int8_lpbq_record_full_u8_offset_result(HmxInt8GateResult *res, int case_id, int variant,
                                                       int pack_mode, const int32_t *corr,
                                                       const int32_t *signed_ref, const int32_t *raw,
                                                       const int32_t *sum_w, int tolerance = 0) {
  int    first_bad = -1;
  int    max_err_i = 0;
  double sq_err = 0.0;
  for (int i = 0; i < 32 * 32; ++i) {
    int err = corr[i] - signed_ref[i];
    if (err < 0) {
      err = -err;
    }
    if (err > max_err_i) {
      max_err_i = err;
      first_bad = i;
    }
    sq_err += (double) err * (double) err;
  }

  const int sample = first_bad >= 0 ? first_bad : 0;
  memset(res, 0, sizeof(*res));
  res->reserved    = case_id;
  res->variant     = variant;
  res->output_kind = max_err_i <= tolerance ? 0 : -57;
  res->tile_bytes  = pack_mode;
  res->selector    = first_bad;
  res->expected    = (float) signed_ref[0];
  res->first8[0]   = (float) corr[0];
  res->first8[1]   = (float) signed_ref[0];
  res->first8[2]   = (float) max_err_i;
  res->first8[3]   = (float) sqrt(sq_err / (32.0 * 32.0));
  res->first8[4]   = (float) raw[0];
  res->first8[5]   = (float) sum_w[0];
  res->first8[6]   = (float) corr[sample];
  res->first8[7]   = (float) signed_ref[sample];
  res->min_value   = (float) max_err_i;
  res->max_value   = (float) max_err_i;
  res->mean_value  = (float) first_bad;
  res->rmse        = res->first8[3];
}

static void hmx_int8_lpbq_fill_uniform_raw_tiles(uint8_t *a, int8_t *b, uint8_t q, int8_t w) {
  memset(a, q, HMX_FP16_TILE_SIZE);
  memset(b, (uint8_t) w, HMX_FP16_TILE_SIZE);
}

static inline int32_t hmx_int8_lpbq_recover_raw_acc_257_256(int32_t scaled_acc) {
  // LPBQ deploy-v1 full-u8 probe note: V73 after.uh writeback for
  // activation.ub*weight.b behaves like floor(raw_acc * 257 / 256).  This
  // inverse is a standalone-verified candidate for recovering the raw integer
  // accumulator before the asymmetric-A8 zero-point correction.
  const int64_t num = (int64_t) scaled_acc * 256LL;
  if (num >= 0) {
    return (int32_t) ((num + 256LL) / 257LL);
  }
  return (int32_t) (-((-num) / 257LL));
}

static int hmx_int8_lpbq_full_u8_offset_probe_run(struct HmxInt8GateResult *results, int max_results) {
  constexpr int n_uniform = 4;
  constexpr int n_variants = 2;
  constexpr int n_act_packs = 3;
  constexpr int n_weight_packs = 2;
  constexpr int n_results = n_uniform + n_variants * n_act_packs * n_weight_packs;
  if (!results || max_results < n_results) {
    return -1;
  }

  uint8_t *vtcm = (uint8_t *) vtcm_manager_get_vtcm_base();
  uint8_t  *a          = vtcm;
  int8_t   *b          = (int8_t *) (vtcm + 0x1000);
  uint16_t *out        = (uint16_t *) (vtcm + 0x2000);
  __fp16   *scales     = (__fp16 *) (vtcm + 0x3000);
  uint8_t  *q_u        = vtcm + 0x4000;
  int8_t   *w_ref      = (int8_t *) (vtcm + 0x5000);
  int32_t  *raw_ref    = (int32_t *) (vtcm + 0x6000);
  int32_t  *signed_ref = (int32_t *) (vtcm + 0x7000);
  int32_t  *sum_w      = (int32_t *) (vtcm + 0x8000);
  int32_t  *raw_hmx    = (int32_t *) (vtcm + 0x9000);
  int32_t  *corr_hmx   = (int32_t *) (vtcm + 0xa000);

  hmx_manager_enable_execution();
  hmx_unit_acquire();
  hmx_gate_init_scales(scales, 0);

  int result_idx = 0;
  const uint8_t uniform_q[n_uniform] = {0, 127, 129, 255};
  const int8_t  uniform_w[n_uniform] = {1, -2, 1, 1};
  for (int ci = 0; ci < n_uniform; ++ci) {
    const uint8_t q = uniform_q[ci];
    const int8_t  w = uniform_w[ci];
    hmx_int8_lpbq_fill_uniform_raw_tiles(a, b, q, w);
    hmx_int8_raw_dot_tile_b_variant_output(a, b, (uint8_t *) out, scales, 8, 16);
    for (int r = 0; r < 32; ++r) {
      for (int c = 0; c < 32; ++c) {
        const int idx = r * 32 + c;
        raw_hmx[idx]    = hmx_int8_lpbq_recover_raw_acc_257_256(
          hmx_gate_decode_uh_signed(out[hmx_tile_idx_32(r, c)]));
        sum_w[c]        = 32 * (int) w;
        signed_ref[idx] = 32 * ((int) q - 128) * (int) w;
        corr_hmx[idx]   = raw_hmx[idx] - 128 * sum_w[c];
      }
    }
    hmx_int8_lpbq_record_full_u8_offset_result(&results[result_idx++], 5700 + ci, 8, 100 + ci, corr_hmx,
                                               signed_ref, raw_hmx, sum_w);
  }

  hmx_int8_lpbq_fill_full_u8_offset_case(q_u, w_ref, raw_ref, signed_ref, sum_w, 1);
  const int variants[n_variants] = {8, 9};
  for (int vi = 0; vi < n_variants; ++vi) {
    const int variant = variants[vi];
    for (int act_pack = 0; act_pack < n_act_packs; ++act_pack) {
      for (int weight_pack = 0; weight_pack < n_weight_packs; ++weight_pack) {
        memset(raw_hmx, 0, 32u * 32u * sizeof(int32_t));
        for (int k_in = 0; k_in < 32; k_in += 4) {
          hmx_int8_lpbq_pack_activation_u8_k4_mode(a, q_u, k_in, act_pack);
          if (weight_pack == 0) {
            hmx_int8_pack_weight_b_full_k4_local(b, w_ref, k_in);
          } else {
            hmx_int8_pack_weight_b_full_k4_local_pair(b, w_ref, k_in);
          }
          hmx_int8_raw_dot_tile_b_variant_output(a, b, (uint8_t *) out, scales, variant, 16);
          for (int r = 0; r < 32; ++r) {
            for (int c = 0; c < 32; ++c) {
              const int idx = r * 32 + c;
              raw_hmx[idx] += hmx_int8_lpbq_recover_raw_acc_257_256(
                hmx_gate_decode_uh_signed(out[hmx_tile_idx_32(r, c)]));
            }
          }
        }
        for (int r = 0; r < 32; ++r) {
          for (int c = 0; c < 32; ++c) {
            const int idx = r * 32 + c;
            corr_hmx[idx] = raw_hmx[idx] - 128 * sum_w[c];
          }
        }
        const int pack_mode = act_pack * 10 + weight_pack;
        hmx_int8_lpbq_record_full_u8_offset_result(&results[result_idx++],
                                                   5710 + variant * 100 + act_pack * 10 + weight_pack, variant,
                                                   pack_mode, corr_hmx, signed_ref, raw_hmx, sum_w);
      }
    }
  }

  hmx_unit_release();
  hmx_manager_disable_execution();

  while (result_idx < max_results) {
    memset(&results[result_idx++], 0, sizeof(HmxInt8GateResult));
  }
  return 0;
}

static int hmx_int8_lpbq_uniform_u8_raw_sweep_probe_run(struct HmxInt8GateResult *results, int max_results) {
  const uint8_t q_values[] = {0,  1,  2,  3,  7,  15, 16, 31, 32, 63, 64, 95, 96,
                              112, 120, 126, 127, 128, 129, 130, 191, 192, 223, 224, 254, 255};
  const int8_t w_values[] = {1, -1};
  constexpr int n_q = (int) (sizeof(q_values) / sizeof(q_values[0]));
  constexpr int n_w = (int) (sizeof(w_values) / sizeof(w_values[0]));
  constexpr int n_results = n_q * n_w;
  if (!results || max_results < n_results) {
    return -1;
  }

  uint8_t *vtcm = (uint8_t *) vtcm_manager_get_vtcm_base();
  uint8_t  *a      = vtcm;
  int8_t   *b      = (int8_t *) (vtcm + 0x1000);
  uint16_t *out    = (uint16_t *) (vtcm + 0x2000);
  __fp16   *scales = (__fp16 *) (vtcm + 0x3000);

  hmx_manager_enable_execution();
  hmx_unit_acquire();
  hmx_gate_init_scales(scales, 0);

  int result_idx = 0;
  for (int qi = 0; qi < n_q; ++qi) {
    for (int wi = 0; wi < n_w; ++wi) {
      const uint8_t q = q_values[qi];
      const int8_t  w = w_values[wi];
      hmx_int8_lpbq_fill_uniform_raw_tiles(a, b, q, w);
      hmx_int8_raw_dot_tile_b_variant_output(a, b, (uint8_t *) out, scales, 8, 16);

      const int got_scaled = hmx_gate_decode_uh_signed(out[hmx_tile_idx_32(0, 0)]);
      const int got_uh     = (int) out[hmx_tile_idx_32(0, 0)];
      const int got_raw    = hmx_int8_lpbq_recover_raw_acc_257_256(got_scaled);
      const int raw_ref    = 32 * (int) q * (int) w;
      const int err        = got_raw - raw_ref;
      const int abs_err    = err < 0 ? -err : err;

      HmxInt8GateResult *res = &results[result_idx++];
      memset(res, 0, sizeof(*res));
      res->reserved    = 5800 + qi * 10 + wi;
      res->variant     = 8;
      res->output_kind = abs_err == 0 ? 0 : -58;
      res->tile_bytes  = 2048;
      res->selector    = (int) q;
      res->expected    = (float) raw_ref;
      res->first8[0]   = (float) got_scaled;
      res->first8[1]   = (float) raw_ref;
      res->first8[2]   = (float) (got_scaled - raw_ref);
      res->first8[3]   = (float) got_raw;
      res->first8[4]   = (float) q;
      res->first8[5]   = (float) w;
      res->first8[6]   = (float) (got_raw - 128 * 32 * (int) w);
      res->first8[7]   = (float) (32 * ((int) q - 128) * (int) w);
      res->min_value   = (float) abs_err;
      res->max_value   = (float) abs_err;
      res->mean_value  = (float) got_uh;
      res->rmse        = (float) abs_err;
    }
  }

  hmx_unit_release();
  hmx_manager_disable_execution();
  return 0;
}

static void hmx_int8_lpbq_pack_activation_u8_full_k32_both_lanes(uint8_t *dst, const uint8_t *q_u) {
  memset(dst, 0, HMX_FP16_TILE_SIZE);
  for (int r = 0; r < 32; ++r) {
    for (int k = 0; k < 32; ++k) {
      const int base = 2 * hmx_tile_idx_32(r, k);
      if (base + 1 < HMX_FP16_TILE_SIZE) {
        const uint8_t q = q_u[r * 32 + k];
        dst[base + 0] = q;
        dst[base + 1] = q;
      }
    }
  }
}

static void hmx_int8_lpbq_pack_activation_u8_full_k32_split_lanes(uint8_t *dst, const uint8_t *q_u) {
  memset(dst, 0, HMX_FP16_TILE_SIZE);
  for (int r = 0; r < 32; ++r) {
    for (int k = 0; k < 32; ++k) {
      const int base = 2 * hmx_tile_idx_32(r, k);
      if (base + 1 < HMX_FP16_TILE_SIZE) {
        const uint8_t q = q_u[r * 32 + k];
        dst[base + 0] = (uint8_t) ((q >> 1) << 1);
        dst[base + 1] = q == 255 ? 255 : (uint8_t) ((q - (q >> 1)) << 1);
      }
    }
  }
}

static void hmx_int8_lpbq_pack_activation_u8_full_k32_mode(uint8_t *dst, const uint8_t *q_u, int act_mode) {
  if (act_mode == 0) {
    hmx_int8_pack_activation_u8_full_k32(dst, q_u);
  } else if (act_mode == 1) {
    hmx_int8_lpbq_pack_activation_u8_full_k32_both_lanes(dst, q_u);
  } else {
    hmx_int8_lpbq_pack_activation_u8_full_k32_split_lanes(dst, q_u);
  }
}

static void hmx_int8_lpbq_pack_weight_b_full_k32_mode(int8_t *dst, const int8_t *w_ref, int weight_mode) {
  memset(dst, 0, HMX_FP16_TILE_SIZE);
  for (int k = 0; k < 32; ++k) {
    for (int c = 0; c < 32; ++c) {
      const int base = 128 * (k / 2) + 4 * c + 2 * (k & 1);
      if (base + 1 < HMX_FP16_TILE_SIZE) {
        const int8_t w = w_ref[k * 32 + c];
        if (weight_mode == 0 || weight_mode == 1) {
          dst[base + 0] = w;
        }
        if (weight_mode == 0 || weight_mode == 2) {
          dst[base + 1] = w;
        }
      }
    }
  }
}

static int hmx_int8_lpbq_full_u8_k32_layout_probe_run(struct HmxInt8GateResult *results, int max_results) {
  constexpr int n_variants = 2;
  constexpr int n_act_modes = 3;
  constexpr int n_weight_modes = 3;
  constexpr int n_results = n_variants * n_act_modes * n_weight_modes;
  if (!results || max_results < n_results) {
    return -1;
  }

  uint8_t *vtcm = (uint8_t *) vtcm_manager_get_vtcm_base();
  uint8_t  *a          = vtcm;
  int8_t   *b          = (int8_t *) (vtcm + 0x1000);
  uint16_t *out        = (uint16_t *) (vtcm + 0x2000);
  __fp16   *scales     = (__fp16 *) (vtcm + 0x3000);
  uint8_t  *q_u        = vtcm + 0x4000;
  int8_t   *w_ref      = (int8_t *) (vtcm + 0x5000);
  int32_t  *raw_ref    = (int32_t *) (vtcm + 0x6000);
  int32_t  *signed_ref = (int32_t *) (vtcm + 0x7000);
  int32_t  *sum_w      = (int32_t *) (vtcm + 0x8000);
  int32_t  *raw_hmx    = (int32_t *) (vtcm + 0x9000);
  int32_t  *corr_hmx   = (int32_t *) (vtcm + 0xa000);

  hmx_int8_lpbq_fill_full_u8_offset_case(q_u, w_ref, raw_ref, signed_ref, sum_w, 1);

  hmx_manager_enable_execution();
  hmx_unit_acquire();
  hmx_gate_init_scales(scales, 0);

  int result_idx = 0;
  const int variants[n_variants] = {8, 9};
  for (int vi = 0; vi < n_variants; ++vi) {
    const int variant = variants[vi];
    for (int act_mode = 0; act_mode < n_act_modes; ++act_mode) {
      for (int weight_mode = 0; weight_mode < n_weight_modes; ++weight_mode) {
        hmx_int8_lpbq_pack_activation_u8_full_k32_mode(a, q_u, act_mode);
        hmx_int8_lpbq_pack_weight_b_full_k32_mode(b, w_ref, weight_mode);
        hmx_int8_raw_dot_tile_b_variant_output(a, b, (uint8_t *) out, scales, variant, 16);
        for (int r = 0; r < 32; ++r) {
          for (int c = 0; c < 32; ++c) {
            const int idx = r * 32 + c;
            raw_hmx[idx] = hmx_int8_lpbq_recover_raw_acc_257_256(
              hmx_gate_decode_uh_signed(out[hmx_tile_idx_32(r, c)]));
            corr_hmx[idx] = raw_hmx[idx] - 128 * sum_w[c];
          }
        }
        const int pack_mode = act_mode * 10 + weight_mode;
        hmx_int8_lpbq_record_full_u8_offset_result(&results[result_idx++],
                                                   5900 + variant * 100 + pack_mode, variant, pack_mode, corr_hmx,
                                                   signed_ref, raw_hmx, sum_w);
      }
    }
  }

  hmx_unit_release();
  hmx_manager_disable_execution();
  return 0;
}

static int hmx_int8_lpbq_full_u8_sparse_map_probe_run(struct HmxInt8GateResult *results, int max_results) {
  struct SparseCase {
    int r;
    int k;
    int c;
    int q;
    int w;
  };
  const SparseCase cases[] = {
    {0, 0, 0, 8, 1},
    {0, 0, 0, 8, -1},
    {0, 1, 0, 8, 1},
    {1, 0, 0, 8, 1},
    {0, 0, 1, 8, 1},
  };
  constexpr int n_cases = (int) (sizeof(cases) / sizeof(cases[0]));
  const int variants[] = {0, 1, 2, 3, 4, 5, 6, 8, 9, 10, 11, 12};
  constexpr int n_variants = (int) (sizeof(variants) / sizeof(variants[0]));
  constexpr int n_act_modes = 3;
  constexpr int n_weight_modes = 3;
  constexpr int n_results = n_cases * n_variants * n_act_modes * n_weight_modes;
  if (!results || max_results < n_results) {
    return -1;
  }

  uint8_t *vtcm = (uint8_t *) vtcm_manager_get_vtcm_base();
  uint8_t  *a      = vtcm;
  int8_t   *b      = (int8_t *) (vtcm + 0x1000);
  uint16_t *out    = (uint16_t *) (vtcm + 0x2000);
  __fp16   *scales = (__fp16 *) (vtcm + 0x3000);
  uint8_t  *q_u    = vtcm + 0x4000;
  int8_t   *w_ref  = (int8_t *) (vtcm + 0x5000);

  hmx_manager_enable_execution();
  hmx_unit_acquire();
  hmx_gate_init_scales(scales, 0);

  int result_idx = 0;
  for (int ci = 0; ci < n_cases; ++ci) {
    const SparseCase sc = cases[ci];
    for (int vi = 0; vi < n_variants; ++vi) {
      const int variant = variants[vi];
      for (int act_mode = 0; act_mode < n_act_modes; ++act_mode) {
        for (int weight_mode = 0; weight_mode < n_weight_modes; ++weight_mode) {
          memset(q_u, 0, 32u * 32u);
          memset(w_ref, 0, 32u * 32u);
          q_u[sc.r * 32 + sc.k] = (uint8_t) sc.q;
          w_ref[sc.k * 32 + sc.c] = (int8_t) sc.w;

          hmx_int8_lpbq_pack_activation_u8_full_k32_mode(a, q_u, act_mode);
          hmx_int8_lpbq_pack_weight_b_full_k32_mode(b, w_ref, weight_mode);
          hmx_int8_raw_dot_tile_b_variant_output(a, b, (uint8_t *) out, scales, variant, 16);

          int first_nonzero = -1;
          int first_value = 0;
          int max_idx = -1;
          int max_abs = 0;
          int max_value = 0;
          int nonzero_count = 0;
          for (int idx = 0; idx < 32 * 32; ++idx) {
            const int v = hmx_int8_lpbq_recover_raw_acc_257_256(hmx_gate_decode_uh_signed(out[idx]));
            const int av = v < 0 ? -v : v;
            if (v != 0) {
              if (first_nonzero < 0) {
                first_nonzero = idx;
                first_value = v;
              }
              ++nonzero_count;
            }
            if (av > max_abs) {
              max_abs = av;
              max_idx = idx;
              max_value = v;
            }
          }

          const int target_idx = hmx_tile_idx_32(sc.r, sc.c);
          const int target_value =
            hmx_int8_lpbq_recover_raw_acc_257_256(hmx_gate_decode_uh_signed(out[target_idx]));
          const int expected = sc.q * sc.w;
          const bool exact_target = target_value == expected && nonzero_count == 1;

          HmxInt8GateResult *res = &results[result_idx++];
          memset(res, 0, sizeof(*res));
          res->reserved    = 6000 + ci;
          res->variant     = variant;
          res->output_kind = exact_target ? 0 : -60;
          res->tile_bytes  = act_mode * 10 + weight_mode;
          res->selector    = target_idx;
          res->expected    = (float) expected;
          res->first8[0]   = (float) target_value;
          res->first8[1]   = (float) expected;
          res->first8[2]   = (float) first_nonzero;
          res->first8[3]   = (float) first_value;
          res->first8[4]   = (float) max_idx;
          res->first8[5]   = (float) max_value;
          res->first8[6]   = (float) nonzero_count;
          res->first8[7]   = (float) target_idx;
          res->min_value   = (float) max_abs;
          res->max_value   = (float) max_abs;
          res->mean_value  = (float) first_nonzero;
          res->rmse        = fabsf((float) target_value - (float) expected);
        }
      }
    }
  }

  hmx_unit_release();
  hmx_manager_disable_execution();
  return 0;
}

static int hmx_int8_lpbq_ub_b_byte_drop_probe_run(struct HmxInt8GateResult *results, int max_results) {
  constexpr int n_offsets = HMX_FP16_TILE_SIZE;
  constexpr int n_results = 2 * n_offsets;
  if (!results || max_results < n_results) {
    return -1;
  }

  uint8_t *vtcm = (uint8_t *) vtcm_manager_get_vtcm_base();
  uint8_t  *a      = vtcm;
  int8_t   *b      = (int8_t *) (vtcm + 0x1000);
  uint16_t *out    = (uint16_t *) (vtcm + 0x2000);
  __fp16   *scales = (__fp16 *) (vtcm + 0x3000);

  hmx_manager_enable_execution();
  hmx_unit_acquire();
  hmx_gate_init_scales(scales, 0);

  memset(a, 1, HMX_FP16_TILE_SIZE);
  memset(b, 1, HMX_FP16_TILE_SIZE);
  hmx_int8_raw_dot_tile_b_variant_output(a, b, (uint8_t *) out, scales, 8, 16);
  const int target_idx = hmx_tile_idx_32(0, 0);
  const int baseline = hmx_int8_lpbq_recover_raw_acc_257_256(hmx_gate_decode_uh_signed(out[target_idx]));

  int result_idx = 0;
  for (int side = 0; side < 2; ++side) {
    for (int offset = 0; offset < n_offsets; ++offset) {
      memset(a, 1, HMX_FP16_TILE_SIZE);
      memset(b, 1, HMX_FP16_TILE_SIZE);
      if (side == 0) {
        a[offset] = 0;
      } else {
        b[offset] = 0;
      }
      hmx_int8_raw_dot_tile_b_variant_output(a, b, (uint8_t *) out, scales, 8, 16);
      const int got = hmx_int8_lpbq_recover_raw_acc_257_256(hmx_gate_decode_uh_signed(out[target_idx]));
      const int drop = baseline - got;

      int first_changed = -1;
      int changed_count = 0;
      int max_drop = 0;
      for (int idx = 0; idx < 32 * 32; ++idx) {
        const int v = hmx_int8_lpbq_recover_raw_acc_257_256(hmx_gate_decode_uh_signed(out[idx]));
        const int d = baseline - v;
        const int ad = d < 0 ? -d : d;
        if (d != 0) {
          if (first_changed < 0) {
            first_changed = idx;
          }
          ++changed_count;
        }
        if (ad > max_drop) {
          max_drop = ad;
        }
      }

      HmxInt8GateResult *res = &results[result_idx++];
      memset(res, 0, sizeof(*res));
      res->reserved    = 6100 + side;
      res->variant     = 8;
      res->output_kind = 0;
      res->tile_bytes  = offset;
      res->selector    = target_idx;
      res->expected    = (float) baseline;
      res->first8[0]   = (float) drop;
      res->first8[1]   = (float) got;
      res->first8[2]   = (float) baseline;
      res->first8[3]   = (float) first_changed;
      res->first8[4]   = (float) changed_count;
      res->first8[5]   = (float) max_drop;
      res->first8[6]   = (float) side;
      res->first8[7]   = (float) offset;
      res->min_value   = (float) drop;
      res->max_value   = (float) max_drop;
      res->mean_value  = (float) changed_count;
      res->rmse        = fabsf((float) drop);
    }
  }

  hmx_unit_release();
  hmx_manager_disable_execution();
  return 0;
}

static int hmx_int8_lpbq_full_u8_shifted_twin_probe_run(struct HmxInt8GateResult *results, int max_results) {
  struct SparseCase {
    int r;
    int k;
    int c;
    int q;
    int w;
  };
  const SparseCase sparse_cases[] = {
    {0, 0, 0, 8, 1},
    {0, 0, 0, 8, -1},
    {0, 1, 0, 8, 1},
    {1, 0, 0, 8, 1},
    {0, 0, 1, 8, 1},
    {0, 7, 3, 255, 1},
  };
  constexpr int n_sparse = (int) (sizeof(sparse_cases) / sizeof(sparse_cases[0]));
  constexpr int n_results = 1 + n_sparse;
  if (!results || max_results < n_results) {
    return -1;
  }

  uint8_t *vtcm = (uint8_t *) vtcm_manager_get_vtcm_base();
  uint8_t  *a          = vtcm;
  int8_t   *b          = (int8_t *) (vtcm + 0x1000);
  uint16_t *out        = (uint16_t *) (vtcm + 0x2000);
  __fp16   *scales     = (__fp16 *) (vtcm + 0x3000);
  uint8_t  *q_u        = vtcm + 0x4000;
  int8_t   *w_ref      = (int8_t *) (vtcm + 0x5000);
  int32_t  *raw_ref    = (int32_t *) (vtcm + 0x6000);
  int32_t  *signed_ref = (int32_t *) (vtcm + 0x7000);
  int32_t  *sum_w      = (int32_t *) (vtcm + 0x8000);
  int32_t  *raw_hmx    = (int32_t *) (vtcm + 0x9000);
  int32_t  *corr_hmx   = (int32_t *) (vtcm + 0xa000);

  hmx_manager_enable_execution();
  hmx_unit_acquire();
  hmx_gate_init_scales(scales, 0);

  hmx_int8_lpbq_fill_full_u8_offset_case(q_u, w_ref, raw_ref, signed_ref, sum_w, 1);
  memset(raw_hmx, 0, 32u * 32u * sizeof(int32_t));
  for (int k_in = 0; k_in < 32; k_in += 4) {
    hmx_int8_lpbq_pack_activation_u8_k4_twin_lanes_shifted(a, q_u, k_in);
    hmx_int8_pack_weight_b_full_k4_local_pair(b, w_ref, k_in);
    hmx_int8_raw_dot_tile_b_variant_output(a, b, (uint8_t *) out, scales, 8, 16);
    for (int r = 0; r < 32; ++r) {
      for (int c = 0; c < 32; ++c) {
        const int idx = r * 32 + c;
        raw_hmx[idx] += hmx_int8_lpbq_recover_raw_acc_257_256(
          hmx_gate_decode_uh_signed(out[hmx_tile_idx_32(r, c)]));
      }
    }
  }
  for (int r = 0; r < 32; ++r) {
    for (int c = 0; c < 32; ++c) {
      const int idx = r * 32 + c;
      corr_hmx[idx] = raw_hmx[idx] - 128 * sum_w[c];
    }
  }
  hmx_int8_lpbq_record_full_u8_offset_result(&results[0], 6200, 8, 31, corr_hmx, signed_ref, raw_hmx, sum_w);

  for (int ci = 0; ci < n_sparse; ++ci) {
    const SparseCase sc = sparse_cases[ci];
    memset(q_u, 0, 32u * 32u);
    memset(w_ref, 0, 32u * 32u);
    memset(raw_hmx, 0, 32u * 32u * sizeof(int32_t));
    q_u[sc.r * 32 + sc.k] = (uint8_t) sc.q;
    w_ref[sc.k * 32 + sc.c] = (int8_t) sc.w;

    for (int k_in = 0; k_in < 32; k_in += 4) {
      hmx_int8_lpbq_pack_activation_u8_k4_twin_lanes_shifted(a, q_u, k_in);
      hmx_int8_pack_weight_b_full_k4_local_pair(b, w_ref, k_in);
      hmx_int8_raw_dot_tile_b_variant_output(a, b, (uint8_t *) out, scales, 8, 16);
      for (int r = 0; r < 32; ++r) {
        for (int c = 0; c < 32; ++c) {
          const int idx = r * 32 + c;
          raw_hmx[idx] += hmx_int8_lpbq_recover_raw_acc_257_256(
            hmx_gate_decode_uh_signed(out[hmx_tile_idx_32(r, c)]));
        }
      }
    }

    int first_nonzero = -1;
    int first_value = 0;
    int max_idx = -1;
    int max_abs = 0;
    int max_value = 0;
    int nonzero_count = 0;
    for (int idx = 0; idx < 32 * 32; ++idx) {
      const int v = raw_hmx[idx];
      const int av = v < 0 ? -v : v;
      if (v != 0) {
        if (first_nonzero < 0) {
          first_nonzero = idx;
          first_value = v;
        }
        ++nonzero_count;
      }
      if (av > max_abs) {
        max_abs = av;
        max_idx = idx;
        max_value = v;
      }
    }

    const int target_idx = sc.r * 32 + sc.c;
    const int target_hmx_idx = hmx_tile_idx_32(sc.r, sc.c);
    const int target_value = raw_hmx[target_idx];
    const int expected = sc.q * sc.w;
    const bool exact_target = target_value == expected && nonzero_count == 1;

    HmxInt8GateResult *res = &results[1 + ci];
    memset(res, 0, sizeof(*res));
    res->reserved    = 6210 + ci;
    res->variant     = 8;
    res->output_kind = exact_target ? 0 : -62;
    res->tile_bytes  = 31;
    res->selector    = target_hmx_idx;
    res->expected    = (float) expected;
    res->first8[0]   = (float) target_value;
    res->first8[1]   = (float) expected;
    res->first8[2]   = (float) first_nonzero;
    res->first8[3]   = (float) first_value;
    res->first8[4]   = (float) max_idx;
    res->first8[5]   = (float) max_value;
    res->first8[6]   = (float) nonzero_count;
    res->first8[7]   = (float) target_hmx_idx;
    res->min_value   = (float) max_abs;
    res->max_value   = (float) max_abs;
    res->mean_value  = (float) first_nonzero;
    res->rmse        = fabsf((float) target_value - (float) expected);
  }

  hmx_unit_release();
  hmx_manager_disable_execution();
  return 0;
}

static int hmx_int8_lpbq_full_u8_singlepass_offset_probe_run(struct HmxInt8GateResult *results, int max_results) {
  struct SparseCase {
    int r;
    int k;
    int c;
    int q;
    int w;
  };
  const SparseCase sparse_cases[] = {
    {0, 0, 0, 8, 1},
    {0, 0, 0, 8, -1},
    {0, 0, 0, 9, 1},
    {0, 0, 0, 255, 1},
    {0, 1, 0, 8, 1},
    {1, 0, 0, 8, 1},
    {0, 0, 1, 8, 1},
    {3, 7, 3, 8, 1},
    {5, 11, 17, 9, -2},
    {30, 0, 0, 8, 1},
    {31, 0, 0, 8, 1},
  };
  constexpr int n_dense = 2;
  constexpr int n_sparse = (int) (sizeof(sparse_cases) / sizeof(sparse_cases[0]));
  constexpr int n_results = n_dense + n_sparse;
  if (!results || max_results < n_results) {
    return -1;
  }

  uint8_t *vtcm = (uint8_t *) vtcm_manager_get_vtcm_base();
  uint8_t  *a          = vtcm;
  int8_t   *b          = (int8_t *) (vtcm + 0x1000);
  uint16_t *out        = (uint16_t *) (vtcm + 0x2000);
  __fp16   *scales     = (__fp16 *) (vtcm + 0x3000);
  uint8_t  *q_u        = vtcm + 0x4000;
  int8_t   *w_ref      = (int8_t *) (vtcm + 0x5000);
  int32_t  *raw_ref    = (int32_t *) (vtcm + 0x6000);
  int32_t  *signed_ref = (int32_t *) (vtcm + 0x7000);
  int32_t  *sum_w      = (int32_t *) (vtcm + 0x8000);
  int32_t  *raw_hmx    = (int32_t *) (vtcm + 0x9000);
  int32_t  *corr_hmx   = (int32_t *) (vtcm + 0xa000);

  hmx_manager_enable_execution();
  hmx_unit_acquire();
  hmx_gate_init_scales(scales, 0);

  int result_idx = 0;
  for (int dense = 0; dense < n_dense; ++dense) {
    hmx_int8_lpbq_fill_full_u8_offset_case(q_u, w_ref, raw_ref, signed_ref, sum_w, dense + 1);
    memset(raw_hmx, 0, 32u * 32u * sizeof(int32_t));
    hmx_int8_lpbq_run_full_u8_singlepass_k32(a, b, out, scales, q_u, w_ref);
    for (int r = 0; r < 32; ++r) {
      for (int c = 0; c < 32; ++c) {
        const int idx = r * 32 + c;
        raw_hmx[idx] = hmx_int8_lpbq_recover_raw_acc_257_256(
          hmx_gate_decode_uh_signed(out[hmx_tile_idx_32(r, c)]));
      }
    }
    for (int r = 0; r < 32; ++r) {
      for (int c = 0; c < 32; ++c) {
        const int idx = r * 32 + c;
        corr_hmx[idx] = raw_hmx[idx] - 128 * sum_w[c];
      }
    }
    // Dense K32 uses one after.uh writeback, so the raw accumulator can differ
    // by a few integer LSBs after the HMX 257/256 output conversion. Sparse
    // layout cases below still require exact q*w.
    hmx_int8_lpbq_record_full_u8_offset_result(&results[result_idx++], 6400 + dense, 8, 64, corr_hmx,
                                               signed_ref, raw_hmx, sum_w, 4);
  }

  for (int ci = 0; ci < n_sparse; ++ci) {
    const SparseCase sc = sparse_cases[ci];
    memset(q_u, 0, 32u * 32u);
    memset(w_ref, 0, 32u * 32u);
    memset(raw_hmx, 0, 32u * 32u * sizeof(int32_t));
    q_u[sc.r * 32 + sc.k] = (uint8_t) sc.q;
    w_ref[sc.k * 32 + sc.c] = (int8_t) sc.w;

    hmx_int8_lpbq_run_full_u8_singlepass_k32(a, b, out, scales, q_u, w_ref);
    for (int r = 0; r < 32; ++r) {
      for (int c = 0; c < 32; ++c) {
        const int idx = r * 32 + c;
        raw_hmx[idx] = hmx_int8_lpbq_recover_raw_acc_257_256(
          hmx_gate_decode_uh_signed(out[hmx_tile_idx_32(r, c)]));
      }
    }

    int first_nonzero = -1;
    int first_value = 0;
    int max_idx = -1;
    int max_abs = 0;
    int max_value = 0;
    int nonzero_count = 0;
    for (int idx = 0; idx < 32 * 32; ++idx) {
      const int v = raw_hmx[idx];
      const int av = v < 0 ? -v : v;
      if (v != 0) {
        if (first_nonzero < 0) {
          first_nonzero = idx;
          first_value = v;
        }
        ++nonzero_count;
      }
      if (av > max_abs) {
        max_abs = av;
        max_idx = idx;
        max_value = v;
      }
    }

    const int target_idx = sc.r * 32 + sc.c;
    const int target_hmx_idx = hmx_tile_idx_32(sc.r, sc.c);
    const int target_value = raw_hmx[target_idx];
    const int expected = sc.q * sc.w;
    const bool exact_target = target_value == expected && nonzero_count == 1;

    HmxInt8GateResult *res = &results[result_idx++];
    memset(res, 0, sizeof(*res));
    res->reserved    = 6410 + ci;
    res->variant     = 8;
    res->output_kind = exact_target ? 0 : -64;
    res->tile_bytes  = 64;
    res->selector    = target_hmx_idx;
    res->expected    = (float) expected;
    res->first8[0]   = (float) target_value;
    res->first8[1]   = (float) expected;
    res->first8[2]   = (float) first_nonzero;
    res->first8[3]   = (float) first_value;
    res->first8[4]   = (float) max_idx;
    res->first8[5]   = (float) max_value;
    res->first8[6]   = (float) nonzero_count;
    res->first8[7]   = (float) target_hmx_idx;
    res->min_value   = (float) max_abs;
    res->max_value   = (float) max_abs;
    res->mean_value  = (float) first_nonzero;
    res->rmse        = fabsf((float) target_value - (float) expected);
  }

  hmx_unit_release();
  hmx_manager_disable_execution();
  return 0;
}

static int hmx_int8_lpbq_full_u8_singlepass_scaled_stress_probe_run(struct HmxInt8GateResult *results,
                                                                    int max_results) {
  constexpr int n_results = 3;
  if (!results || max_results < n_results) {
    return -1;
  }

  uint8_t *vtcm = (uint8_t *) vtcm_manager_get_vtcm_base();
  uint8_t  *a       = vtcm;
  int8_t   *b       = (int8_t *) (vtcm + 0x1000);
  uint16_t *out     = (uint16_t *) (vtcm + 0x2000);
  __fp16   *scales  = (__fp16 *) (vtcm + 0x3000);
  uint8_t  *q_u     = vtcm + 0x4000;
  int8_t   *w_ref   = (int8_t *) (vtcm + 0x5000);
  int32_t  *cpu_ref = (int32_t *) (vtcm + 0x6000);
  int32_t  *acc     = (int32_t *) (vtcm + 0x7000);

  hmx_manager_enable_execution();
  hmx_unit_acquire();
  hmx_int8_lpbq_init_power2_scales(scales, 1.0f / 32.0f);

  for (int pattern = 0; pattern < n_results; ++pattern) {
    hmx_int8_lpbq_fill_u8_scaled_k32_case(q_u, w_ref, cpu_ref, pattern);
    memset(acc, 0, 32u * 32u * sizeof(int32_t));

    hmx_int8_lpbq_run_full_u8_singlepass_k32(a, b, out, scales, q_u, w_ref);
    for (int r = 0; r < 32; ++r) {
      for (int c = 0; c < 32; ++c) {
        const int idx = r * 32 + c;
        const int hmx_idx = hmx_tile_idx_32(r, c);
        // The HMX output scale keeps full-U8 K32 inside after.uh.  Shift back
        // and undo the V73 257/256 output conversion before int32-side
        // zero-point correction.
        acc[idx] = hmx_int8_lpbq_recover_raw_acc_257_256(hmx_gate_decode_uh_signed(out[hmx_idx]) << 5);
      }
    }

    hmx_int8_lpbq_record_acc_probe(&results[pattern], 6700 + pattern, 8, 67, acc, cpu_ref, 1.0f / 32.0f, 512);
  }

  hmx_unit_release();
  hmx_manager_disable_execution();
  return 0;
}

