  for (int it = 0; it < iterations; ++it) {
    lpbq_probe_pack_r4_q_u8_v6_full_k(packed, q_u, k_total);
    checksum += (float) packed[(it * 997) % pack_bytes];
  }
  const int64_t t1 = HAP_perf_get_qtimer_count();
  g_lpbq_r4_prelayout_timing_sink += checksum;
