static void lpbq_probe_direct_pack_r4_q_u8_v6_full_k_rowmajor(uint8_t *packed, const float *activation,
                                                              const float *r4_layout, int active_rows,
                                                              int k_total, bool col8x32_layout) {
  const int k_tiles = k_total / 32;
  memset(packed, 0, (size_t) k_tiles * HMX_FP16_TILE_SIZE);
  for (int r = 0; r < active_rows; ++r) {
    const int row_base = 128 * (r / 2);
    const int row_lane = (r & 1) ? 3 : 1;
    for (int block_start = 0; block_start < k_total; block_start += 128) {
      const float *src_block = activation + (size_t) r * (size_t) k_total + (size_t) block_start;
      const int block_tile = (block_start / 128) * 4;
      for (int col = 0; col < 128; ++col) {
        const int kt = block_tile + (col >> 5);
        const int kk = col & 31;
        const int global_k = block_start + col;
        uint8_t *tile = packed + (size_t) kt * HMX_FP16_TILE_SIZE;
        const float dot = col8x32_layout ?
                            lpbq_probe_r4_dot_col8x32(src_block, r4_layout, 0, col) :
                            lpbq_probe_r4_dot_col_major(src_block, r4_layout, 0, col);
        const int8_t q_s = quantize_probe_f32_to_i8(dot, lpbq_probe_r4_quant_scale_for_col(global_k));
        const int off = row_base + 4 * kk + row_lane;
        if (off >= 0 && off < HMX_FP16_TILE_SIZE) {
          tile[off] = (uint8_t) ((int) q_s + 128);
        }
      }
    }
  }
}

