  res->first8[2] = direct_us;
  res->first8[3] = direct_us > 0.0f ? old_us / direct_us : 0.0f;
  res->first8[4] = direct_us > 0.0f ? current_us / direct_us : 0.0f;
  res->first8[5] = (float) old_new_pack_mismatch;
  res->first8[6] = (float) direct_new_pack_mismatch;
  res->first8[7] = (float) iterations;
  res->min_value = (float) first_bad;
  res->max_value = (float) direct_new_pack_mismatch;
  res->mean_value = old_us;
  res->rmse = direct_us;
  res->nan_count = old_new_pack_mismatch;
  return res->output_kind == 0 ? 0 : -1;
