  __fp16   *out_hf = (__fp16 *) ((uint8_t *) out_uh + HMX_FP16_TILE_SIZE);
  __fp16   *scales = (__fp16 *) ((uint8_t *) out_hf + HMX_FP16_TILE_SIZE);
