  summary->first8[1] = results[1].first8[1];
  summary->first8[2] = results[2].first8[0];
  summary->first8[3] = (float) split_any_formula_close;
  summary->first8[4] = (float) best_any_formula_close;
  summary->first8[5] = (float) best_any_scale_close;
  summary->first8[6] = (float) best_any_raw_close;
  summary->first8[7] = best_any_formula_err;
  summary->selector = best_selector;
  summary->expected = (float) best_any_formula_close;
  summary->tile_bytes = best_pos_formula_close;
  summary->min_value = (float) best_any_scale_close;
  summary->max_value = (float) best_any_raw_close;
  summary->mean_value = best_any_formula_err;
  summary->rmse = best_any_formula_err;
  summary->nan_count = 0;

  hmx_unit_release();
  hmx_manager_disable_execution();
