  uint8_t  *byte_a = vtcm;
  int8_t   *byte_b = (int8_t *) (byte_a + stream_bytes);
  __fp16   *fp_a = (__fp16 *) ((uint8_t *) byte_b + stream_bytes);
  __fp16   *fp_b = (__fp16 *) ((uint8_t *) fp_a + stream_bytes);
  uint16_t *out_uh = (uint16_t *) ((uint8_t *) fp_b + stream_bytes);
  __fp16   *out_hf = (__fp16 *) ((uint8_t *) out_uh + HMX_FP16_TILE_SIZE);
  __fp16   *scales = (__fp16 *) ((uint8_t *) out_hf + HMX_FP16_TILE_SIZE);
  uint32_t *bias_slot = (uint32_t *) ((uint8_t *) scales + 256u);
  uint32_t *readback_slot = (uint32_t *) ((uint8_t *) bias_slot + 256u);
  uint32_t *expected_slot = (uint32_t *) ((uint8_t *) readback_slot + 256u);

  float out_scale[32];
  float bias_eff[32];
  float base_bias[32];
  float sum_w[32];
  float byte_cols[32];
  float got_cols[32];
  float fp_base_cols[32];
  hmx_int8_mode241_fill_per_column_folded_bias(out_scale, bias_eff,
                                               base_bias, sum_w);
  for (int c = 0; c < 32; ++c) {
    fp_base_cols[c] = 32.0f * (float) group_tiles;
  }

  memset(results, 0, (size_t) n_results * sizeof(*results));
  memset(byte_a, 1, stream_bytes);
  memset(byte_b, 1, stream_bytes);
  hmx_gate_init_scales(scales, 0);

  hmx_manager_enable_execution();
  hmx_unit_acquire();

  int row = 0;
  hmx_gate_build_bias256_from_f32(bias_slot, out_scale, bias_eff, 1.0f);
  memcpy(expected_slot, bias_slot, 256u);
  memset(readback_slot, 0xa5, 256u);
  hmx_load_bias_set_from_vtcm_intrinsic(bias_slot, 0);
  hmx_store_bias_set_to_vtcm_intrinsic(readback_slot, 0);
  int payload_mismatches = 0;
  for (int i = 0; i < 64; ++i) {
    if (readback_slot[i] != expected_slot[i]) {
      ++payload_mismatches;
    }
  }
  hmx_int8_mode241_record_value(&results[row++], 24400, 0, 0,
                                (float) payload_mismatches, 0.0f,
                                (float) readback_slot[0],
                                (float) expected_slot[0],
                                (float) readback_slot[63]);

  hmx_int8_mode241_fp16_per_column(fp_a, fp_b, out_hf, bias_slot,
                                   group_tiles, out_scale, bias_eff, 0);
  hmx_int8_mode191_collect_hf_cols(got_cols, out_hf);
  hmx_int8_mode241_record_scan(&results[row++], 24401, 1, 1,
                               got_cols, fp_base_cols, out_scale, bias_eff,
                               0.5f);

  hmx_int8_mode226_byte_fullstream_direct(byte_a, byte_b, scales, out_uh,
                                          group_tiles);
  hmx_int8_mode191_collect_uh_cols(byte_cols, out_uh);
  hmx_int8_mode241_record_scan(&results[row++], 24410, 2, 16,
                               byte_cols, byte_cols, out_scale, bias_eff,
                               0.5f);

  hmx_int8_mode241_byte_after_uh_per_column(byte_a, byte_b, scales, out_uh,
                                            bias_slot, group_tiles, out_scale,
                                            bias_eff, 0);
  hmx_int8_mode191_collect_uh_cols(got_cols, out_uh);
  hmx_int8_mode241_record_scan(&results[row++], 24420, 3, 16,
                               got_cols, byte_cols, out_scale, bias_eff,
                               0.5f);

  hmx_int8_mode244_byte_cvt_uh_sdk_per_column(byte_a, byte_b, scales,
                                              out_uh, bias_slot,
                                              group_tiles, out_scale,
                                              bias_eff, 0);
  hmx_int8_mode191_collect_uh_cols(got_cols, out_uh);
  hmx_int8_mode241_record_scan(&results[row++], 24430, 4, 1,
                               got_cols, byte_cols, out_scale, bias_eff,
                               0.5f);

  hmx_int8_mode244_byte_cvt_uh_sdk_per_column(byte_a, byte_b, scales,
                                              out_uh, bias_slot,
                                              group_tiles, out_scale,
                                              bias_eff, 1);
  hmx_int8_mode191_collect_uh_cols(got_cols, out_uh);
  hmx_int8_mode241_record_scan(&results[row++], 24440, 5, 1,
                               got_cols, byte_cols, out_scale, bias_eff,
                               0.5f);

  const int payload_ok = payload_mismatches == 0 ? 1 : 0;
  const int fp_formula_close = (int) results[1].first8[1];
  const int direct_scale_close = (int) results[3].first8[0];
  const int direct_formula_close = (int) results[3].first8[1];
  const int cvt_uh_2x1_scale_close = (int) results[4].first8[0];
  const int cvt_uh_2x1_formula_close = (int) results[4].first8[1];
  const int cvt_uh_2x2_scale_close = (int) results[5].first8[0];
  const int cvt_uh_2x2_formula_close = (int) results[5].first8[1];
  const float best_formula_err = fminf(fminf(results[3].first8[7],
                                            results[4].first8[7]),
                                      results[5].first8[7]);
  int best_surface = 16;
  if (results[4].first8[7] <= best_formula_err) {
    best_surface = 1;
  }
  if (results[5].first8[7] <= best_formula_err) {
    best_surface = 2;
  }

  hmx_int8_mode241_record_value(&results[row++], 24490, 90, best_surface,
                                best_formula_err, 0.0f, byte_cols[0],
                                out_scale[0], bias_eff[0]);
  HmxInt8GateResult *summary = &results[row - 1];
  summary->first8[0] = (float) payload_ok;
