    hmx_int8_raw_issue_tile_b(a1_lo, w, scales);
    hmx_int8_accumulate_uh_tile_hvx_layout(p0_hi, out0_hi, 0);
    hmx_int8_raw_drain_tile_b(out1_lo);
    hmx_int8_raw_issue_tile_b(a1_hi, w, scales);
