  int8_t   *a_ref   = (int8_t *) (vtcm + 0x5000);
  int8_t   *w_ref   = (int8_t *) (vtcm + 0x6000);
  int32_t  *cpu_ref = (int32_t *) (vtcm + 0x7000);
  int32_t  *acc     = (int32_t *) (vtcm + 0x9000);

  hmx_gate_init_scales(scales, 0);
  hmx_manager_enable_execution();
