void benchmark_vtcm_bandwidth() {
  uint8_t *vtcm = (uint8_t *) vtcm_manager_get_vtcm_base();

  HVX_Vector *a = (HVX_Vector *) vtcm;
  HVX_Vector *b = (HVX_Vector *) (vtcm + 0x400000);

  size_t size = 0x100000;

  int64_t t0 = HAP_perf_get_qtimer_count();
  for (int i = 0; i < size / VLEN; ++i) {
    // HVX_Vector v0 = *a++;
    // HVX_Vector v1 = *a++;
    // HVX_Vector v2 = *a++;
    // *b++ = v0;
    // *b++ = v1;
    // *b++ = v2;

    // 4 packets
    // asm volatile (
    //   "{ v0.cur = vmem(%0++#1)\n"
    //   " vmem(%1++#1) = v0 }\n"
    //   "{ v1.cur = vmem(%0++#1)\n"
    //   " vmem(%1++#1) = v1 }\n"
    //   "vmem(%1++#1) = v0\n"
    //   "vmem(%1++#1) = v1\n"
    //   :"+r"(a), "+r"(b)::"v0", "v1"
    // );

    // 3 packets
    // asm volatile(
    //   "{ v0.cur = vmem(%0++#1)\n"
    //   " vmem(%1++#1) = v0 }\n"
    //   "{ v1.cur = vmem(%0++#1)\n"
    //   " vmem(%1++#1) = v1 }\n"
    //   "{ v2.cur = vmem(%0++#1)\n"
    //   " vmem(%1++#1) = v2 }\n"
    //   : "+r"(a), "+r"(b)::"v0", "v1", "v2");

    asm volatile(
      "{ v0.cur = vmem(%0++#1)\n"
      " vmem(%1++#1) = v0 }\n"
      "{ v1.cur = vmem(%0++#1)\n"
      " vmem(%1++#1) = v1 }\n"
      "{ v2.cur = vmem(%0++#1)\n"
      " vmem(%1++#1) = v2 }\n"
      "{ v3.cur = vmem(%0++#1)\n"
      " vmem(%1++#1) = v3 }\n"
      : "+r"(a), "+r"(b)::"v0", "v1", "v2", "v3");
  }
  int64_t t1         = HAP_perf_get_qtimer_count();
  int64_t elapsed_us = HAP_perf_qtimer_count_to_us(t1 - t0);

  const int rf       = 4;
  const int tf       = 8;
  double    read_bw  = 1e-3 * rf * size / elapsed_us;
  double    total_bw = 1e-3 * tf * size / elapsed_us;

  FARF(ALWAYS, "%s: %lld us, read bw: %.2lf GB/s, total bw: %.2lf GB/s", __func__, elapsed_us, read_bw, total_bw);
}

